import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';
import {binding,branch,marker,trainingTeacherPlan,trainingTeacherOutputs} from './training-teacher-scope.mjs';
import {requiredChecks,failedChecks} from './merge-gate.mjs';import {admitLocal} from './training-teacher-checks.mjs';
function fixture(){const head='a'.repeat(40),source='b'.repeat(40),values={};const entries=Object.entries(binding.source).map(([file,s])=>({file,...s}));for(const file of binding.controls){const b=binding.controlBefore[file];entries.push({file,status:b?'M':'A',oldMode:b?'100644':'000000',newMode:'100644'});if(b)values[binding.base+':'+file]=b}for(const[file,s]of Object.entries(binding.source)){if(s.before)values[binding.base+':'+file]=s.before;values[head+':'+file]=s.after}for(const[c,t]of Object.entries(binding.components))values[head+':server-version/'+c]=t;for(const[f,b]of Object.entries(binding.protectedInputs))values[head+':'+f]=b;values[head+'^{tree}']='tree';values[source+'^{tree}']='tree';const env={CI_EVENT:'pull_request',CI_HEAD_REF:branch,CI_SOURCE_HEAD:source,CI_PR_REPOSITORY:'caohuibj/eduK12-new-version',CI_PR_NUMBER:'348'};const read=(cmd,arg)=>{assert.equal(cmd,'rev-parse');assert(arg in values,arg);return values[arg]};return {head,source,entries,env,values,read,plan(){return trainingTeacherPlan(this.entries,binding.base,this.head,this.read,this.env)}}}
test('exact candidate disables unrelated work and keeps fresh SAST',()=>{const o=trainingTeacherOutputs(fixture().plan());for(const k of ['frontend','frontend_build','maintenance','run_performance_tests','ops','media2'])assert.equal(o[k],false);assert.equal(o.codeql,true)});
for(const[name,mutate]of [['missing marker',f=>f.entries.splice(f.entries.findIndex(e=>e.file===marker),1)],['unknown path',f=>f.entries[0].file='unknown.ts'],['missing file',f=>f.entries.pop()],['duplicate path',f=>f.entries[0]=f.entries[1]],['executable',f=>f.entries[0].newMode='100755'],['deletion',f=>f.entries[0].status='D'],['source drift',f=>f.values[f.head+':'+Object.keys(binding.source)[0]]='c'.repeat(40)],['component drift',f=>f.values[f.head+':server-version/backend']='c'.repeat(40)],['merge drift',f=>f.values[f.source+'^{tree}']='different'],['wrong branch',f=>f.env.CI_HEAD_REF='other'],['wrong repo',f=>f.env.CI_PR_REPOSITORY='other/repo'],['manual',f=>f.env.CI_EVENT='workflow_dispatch'],['full',f=>f.env.CI_FORCE_FULL='true']])test('rejects '+name,()=>{const f=fixture();mutate(f);assert.throws(()=>f.plan())});
test('base drift and missing success never qualify',()=>{const f=fixture();assert.throws(()=>trainingTeacherPlan(f.entries,'c'.repeat(40),f.head,f.read,f.env));const outputs=Object.fromEntries(Object.entries(trainingTeacherOutputs(f.plan())).map(([k,v])=>[k,String(v)]));const n={scope:{result:'success',outputs},'training-teacher-management':{result:'success'},codeql:{result:'success'}};assert.deepEqual(requiredChecks(n,false),['scope','training-teacher-management','codeql']);assert.deepEqual(failedChecks(n,false),[]);assert(failedChecks(n,true).length);for(const result of ['failure','skipped','cancelled',undefined])for(const job of Object.keys(n)){const a=structuredClone(n);a[job].result=result;assert(failedChecks(a,false).includes(job))}});
test('only exact main push classifies without replay',()=>{const f=fixture();Object.assign(f.env,{CI_EVENT:'push',CI_HEAD_REF:'main',GITHUB_REF_NAME:'main'});assert.equal(trainingTeacherOutputs(f.plan()).codeql,false)});
test('admits original local reports honestly and rejects tampering',()=>{assert.equal(admitLocal().acceptedCases,78);assert.throws(()=>admitLocal(()=>Buffer.from('{}')));assert.throws(()=>admitLocal(readFileSync,()=> 'c'.repeat(40)))});
test('bounded workflow performs missing DB HTTP and build only',()=>{const s=readFileSync('.github/workflows/ci.yml','utf8'),w=s.slice(s.indexOf('  training-teacher-management:'),s.indexOf('  training-admin-admission:'));assert(w.includes('training-teacher-checks.mjs migration'));assert(w.includes('training-teacher-http.cjs'));assert.equal((w.match(/vite\.js build/g)||[]).length,1);for(const text of ['npm test','tsc --noEmit','vitest','docker build','uses: ./.github/workflows/'])assert(!w.includes(text));assert(s.includes('training_teacher_plan: ${{ steps.scope.outputs.training_teacher_plan }}'));assert(s.includes("application_route != 'training-teacher-management'"));assert(s.includes("application_route == 'training-teacher-management' && 'paths:"))});
